       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'defended_only' THEN denominator_unit END) AS at_token_cap_retokenized__defended_only_unit,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'defended_only' THEN measurement_state END) AS at_token_cap_retokenized__defended_only_state,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'first_512_tokens' THEN rate END) AS at_token_cap_retokenized__first_512_tokens_rate,
