       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'first_512_tokens' THEN denominator_unit END) AS at_token_cap_retokenized__first_512_tokens_unit,
       MAX(CASE WHEN measure = 'at_token_cap_retokenized' AND scope = 'first_512_tokens' THEN measurement_state END) AS at_token_cap_retokenized__first_512_tokens_state,
